files.content:
:root {
  --bg: #1b1b2f;
  --card: #2a2a45;
  --accent: #ff6b6b;
  --accent2: #4ecdc4;
  --text: #f4f4f9;
  --muted: #9a9ab0;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
  background: var(--bg);
  background-image:
    linear-gradient(45deg, rgba(255,255,255,0.03) 25%, transparent 25%),
    linear-gradient(-45deg, rgba(255,255,255,0.03) 25%, transparent 25%);
  background-size: 16px 16px;
  font-family: ui-monospace, 'Courier New', monospace;
  font-size: 16px;
  color: var(--text);
}

.card {
  width: 100%;
  max-width: 420px;
  background: var(--card);
  border: 4px solid var(--text);
  border-radius: 4px;
  padding: 32px 24px;
  text-align: center;
  box-shadow: 8px 8px 0 rgba(0,0,0,0.4);
}

.title {
  margin: 0 0 24px;
  font-size: 20px;
  letter-spacing: 2px;
  color: var(--accent2);
}

.modes {
  display: flex;
  gap: 12px;
  margin-bottom: 24px;
}

.mode-btn {
  flex: 1;
  padding: 12px 8px;
  font-family: inherit;
  font-size: 16px;
  font-weight: bold;
  color: var(--text);
  background: transparent;
  border: 3px solid var(--muted);
  border-radius: 4px;
  cursor: pointer;
  transition: transform 0.05s, background 0.15s, border-color 0.15s;
}

.mode-btn:hover { border-color: var(--accent2); }
.mode-btn:focus-visible { outline: 3px solid var(--accent2); outline-offset: 2px; }
.mode-btn.active { background: var(--accent2); color: var(--bg); border-color: var(--accent2); }
.mode-btn:active { transform: translateY(2px); }

.countdown {
  font-size: clamp(56px, 20vw, 96px);
  font-weight: bold;
  line-height: 1;
  margin: 16px 0 24px;
  letter-spacing: 2px;
  color: var(--text);
  font-variant-numeric: tabular-nums;
  text-shadow: 4px 4px 0 rgba(0,0,0,0.3);
}

.controls {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.ctrl {
  flex: 1;
  min-width: 90px;
  padding: 14px 8px;
  font-family: inherit;
  font-size: 16px;
  font-weight: bold;
  color: var(--text);
  background: var(--bg);
  border: 3px solid var(--muted);
  border-radius: 4px;
  cursor: pointer;
  transition: transform 0.05s, background 0.15s, border-color 0.15s;
}

.ctrl:hover { border-color: var(--accent); }
.ctrl:focus-visible { outline: 3px solid var(--accent2); outline-offset: 2px; }
.ctrl:active { transform: translateY(2px); }
.ctrl.primary { background: var(--accent); border-color: var(--accent); color: var(--bg); }
.ctrl.primary:hover { filter: brightness(1.1); }

.status {
  margin: 20px 0 0;
  font-size: 16px;
  color: var(--muted);
  min-height: 20px;
}

@media (max-width: 380px) {
  .card { padding: 24px 16px; }
  .controls { flex-direction: column; }
}

(function () {
  'use strict';

  var WORK_SECONDS = 25 * 60;
  var BREAK_SECONDS = 5 * 60;

  var countdownEl = document.getElementById('countdown');
  var startBtn = document.getElementById('startBtn');
  var pauseBtn = document.getElementById('pauseBtn');
  var resetBtn = document.getElementById('resetBtn');
  var workBtn = document.getElementById('workBtn');
  var breakBtn = document.getElementById('breakBtn');
  var statusEl = document.getElementById('status');

  var mode = 'work';
  var remaining = WORK_SECONDS;
  var running = false;
  var endTime = 0;
  var intervalId = null;

  function formatTime(totalSeconds) {
    var m = Math.floor(totalSeconds / 60);
    var s = totalSeconds % 60;
    return (m < 10 ? '0' : '') + m + ':' + (s < 10 ? '0' : '') + s;
  }

  function render() {
    countdownEl.textContent = formatTime(remaining);
  }

  function stopInterval() {
    if (intervalId !== null) {
      clearInterval(intervalId);
      intervalId = null;
    }
  }

  function tick() {
    var now = Date.now();
    var secsLeft = Math.max(0, Math.round((endTime - now) / 1000));
    if (secsLeft !== remaining) {
      remaining = secsLeft;
      render();
    }
    if (remaining <= 0) {
      stopInterval();
      running = false;
      statusEl.textContent = mode === 'work' ? 'Work complete! Take a break.' : 'Break over! Back to work.';
    }
  }

  function start() {
    if (running) return;
    if (remaining <= 0) return;
    running = true;
    endTime = Date.now() + remaining * 1000;
    stopInterval();
    intervalId = setInterval(tick, 250);
    statusEl.textContent = 'Running...';
  }

  function pause() {
    if (!running) return;
    tick();
    stopInterval();
    running = false;
    statusEl.textContent = 'Paused';
  }

  function reset() {
    stopInterval();
    running = false;
    remaining = mode === 'work' ? WORK_SECONDS : BREAK_SECONDS;
    render();
    statusEl.textContent = 'Ready';
  }

  function setMode(newMode) {
    mode = newMode;
    workBtn.classList.toggle('active', mode === 'work');
    breakBtn.classList.toggle('active', mode === 'break');
    workBtn.setAttribute('aria-pressed', String(mode === 'work'));
    breakBtn.setAttribute('aria-pressed', String(mode === 'break'));
    reset();
  }

  startBtn.addEventListener('click', start);
  pauseBtn.addEventListener('click', pause);
  resetBtn.addEventListener('click', reset);
  workBtn.addEventListener('click', function () { setMode('work'); });
  breakBtn.addEventListener('click', function () { setMode('break'); });

  render();
})();
